function match(answers,opt={}){
 if(!Array.isArray(answers)||answers.length!==25||answers.some(v=>v!=='unknown'&&(!Number.isInteger(v)||v<0||v>4)))throw Error('25개 유효 응답 필요');
 const limit=Number.isInteger(opt.limit)?Math.max(0,Math.min(10,opt.limit)):4;
 const min=Number.isInteger(opt.threshold)?Math.max(1,Math.min(4,opt.threshold)):2;
 return DATA.entries.filter(e=>e.items.every(n=>typeof answers[n-1]==='number'&&answers[n-1]>=min)).sort((a,b)=>Number(b.safetyOverride)-Number(a.safetyOverride)||Number(a.sameEventCheck)-Number(b.sameEventCheck)||Math.max(...b.items.map(n=>answers[n-1]))-Math.max(...a.items.map(n=>answers[n-1]))||a.id.localeCompare(b.id)).slice(0,limit);
}
const api={version:DATA.version,asOf:DATA.asOf,entries:DATA.entries,sourceNotice:DATA.sourceNotice,match};
if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.YouthResearchKB=api;
